INSERT INTO `product` VALUES (1,4,'Savon Beauté','savon-beauté','<ul><li><strong><br>Savon Beauté Bio</strong> - <em>L\'Art du Soin Naturel<br></em><br><br>Fabriqué ├á la main par notre coopérative marocaine selon des méthodes traditionnelles, ce savon bio allie <strong>pureté des ingrédients</strong> et <strong>respect de la peau</strong>.<br><br><br>Ô£¿ <strong>Ce qui le rend exceptionnel</strong> :<br><br><ul><li><strong>100% naturel</strong> : Sans parab├¿nes, sans colorants chimiques, sans parfums synthétiques</li><li><strong>Ingrédients locaux</strong> : Huile d\'argan bio, huile d\'olive vierge extra et plantes du terroir</li><li><strong>Double action</strong> : Nettoie en douceur tout en nourrissant la peau</li><li><strong>├ëcoresponsable</strong> : Emballage biodégradable, production artisanale ├á faible impact environnemental</li></ul></li><li><br>­ƒÆÜ <strong>Pour qui ?<br></strong><br><ul><li>Peaux sensibles, s├¿ches ou ├á imperfections</li><li>Ceux qui privilégient les produits authentiques et éthiques</li><li>Les amoureux des rituels de beauté naturels</li></ul></li><li><em><br>\"Un retour aux sources pour une peau rayonnante de santé\"<br></em><br></li></ul>','31-07-2025-26-07-2025-savon-fleurs-redim-f4e5fb41ad00b505ee7d77ee2b669bdc67bb79e1-f4e5fb41ad00b505ee7d77ee2b669bdc67bb79e1.jpg',45,20,1),(2,4,'Savon Fleurs','savon-fleurs','<div><strong><br>Savon Beauté Bio</strong> - <em>L\'Art du Soin Naturel<br></em><br></div><div><br>Fabriqué ├á la main par notre coopérative marocaine selon des méthodes traditionnelles, ce savon bio allie <strong>pureté des ingrédients</strong> et <strong>respect de la peau</strong>.<br><br></div><div><br>Ô£¿ <strong>Ce qui le rend exceptionnel</strong> :<br><br></div><ul><li><strong>100% naturel</strong> : Sans parab├¿nes, sans colorants chimiques, sans parfums synthétiques</li><li><strong>Ingrédients locaux</strong> : Huile d\'argan bio, huile d\'olive vierge extra et plantes du terroir</li><li><strong>Double action</strong> : Nettoie en douceur tout en nourrissant la peau</li><li><strong>├ëcoresponsable</strong> : Emballage biodégradable, production artisanale ├á faible impact environnemental</li></ul><div><br>­ƒÆÜ <strong>Pour qui ?<br></strong><br></div><ul><li>Peaux sensibles, s├¿ches ou ├á imperfections</li><li>Ceux qui privilégient les produits authentiques et éthiques</li><li>Les amoureux des rituels de beauté naturels</li></ul><div><em><br>\"Un retour aux sources pour une peau rayonnante de santé\"<br></em><br></div>','31-07-2025-26-07-2025-savons-fleurs-redim-0db7ee5ed9cb035af08ebec186c2afc3cf4e3daa-0db7ee5ed9cb035af08ebec186c2afc3cf4e3daa.jpg',45,20,1),(3,5,'Savon Classique','savon-classique','<div><strong><br>Savon Beldi Traditionnel</strong> - <em>Le Secret de Beauté Marocain Depuis des Générations<br></em><br></div><div><br>Elaboré selon la <strong>recette ancestrale marocaine</strong>, ce savon noir 100% naturel est un trésor de <strong>nettoyage profond</strong> et de <strong>purification de la peau</strong>.<br><br></div><div><br>­ƒî┐ <strong>Caractéristiques uniques</strong> :<br><br></div><ul><li><strong>Texture onctueuse</strong> : Mélange d\'huile d\'olive et d\'extraits de plantes</li><li><strong>Gommage doux</strong> : Efficace sans agresser l\'épiderme</li><li><strong>Rituel Hammam</strong> : Indissociable du gant de Kessa pour un gommage parfait</li><li><strong>Multi-usages</strong> : Corps, visage et m├¬me cheveux</li></ul><div><br>Ô£¿ <strong>Pourquoi l\'adorer ?<br></strong><br></div><ul><li><strong>Détoxifie</strong> en éliminant les impuretés</li><li><strong>Prépare la peau</strong> ├á mieux absorber les soins (comme l\'huile d\'argan)</li><li><strong>Rend la peau douce</strong> comme apr├¿s un soin en institut</li></ul><div><br>­ƒºûÔÇìÔÖÇ´©Å <strong>Usage typique</strong> :<br><br></div><ol><li>Appliquer sur peau humide</li><li>Masser en circulaire avec le gant de Kessa</li><li>Rincer ├á l\'eau ti├¿de</li><li>Profiter d\'une peau neuve et rayonnante</li>